#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(max(N,2), false);
    {
        vector<bool> sieve(max(N,2), true);
        sieve[0]=sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i]) for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    // step is 1-indexed: edge from tour[step-1] to tour[step]
    auto getmult = [&](int step, int src) -> double {
        return (step%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto edgeCost = [&](int step, int from, int to) -> double {
        return ddist(from,to) * getmult(step, from);
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++) cost += edgeCost(s, t[s-1], t[s]);
        return cost;
    };

    // Nearest neighbor with grid acceleration
    auto buildNN = [&](int startCity) -> vector<int> {
        double minx=1e18,maxx=-1e18,miny=1e18,maxy=-1e18;
        for(int i=0;i<N;i++){
            minx=min(minx,cx[i]);maxx=max(maxx,cx[i]);
            miny=min(miny,cy[i]);maxy=max(maxy,cy[i]);
        }
        int gs=max(1,(int)sqrt((double)N/4.0));
        double cW=(maxx-minx)/gs+1e-9, cH=(maxy-miny)/gs+1e-9;
        if(cW<1e-12)cW=1; if(cH<1e-12)cH=1;

        auto cell=[&](int i)->pair<int,int>{
            return {min(gs-1,max(0,(int)((cx[i]-minx)/cW))),
                    min(gs-1,max(0,(int)((cy[i]-miny)/cH)))};
        };
        auto idx=[&](int gx,int gy)->int{return gy*gs+gx;};

        vector<vector<int>> gr(gs*gs);
        for(int i=0;i<N;i++){auto[gx,gy]=cell(i);gr[idx(gx,gy)].push_back(i);}

        vector<bool> vis(N,false);
        vector<int> t(N+1);
        t[0]=startCity; vis[startCity]=true;
        {auto[gx,gy]=cell(startCity);auto&v=gr[idx(gx,gy)];v.erase(find(v.begin(),v.end(),startCity));}

        for(int step=1;step<N;step++){
            int last=t[step-1];
            auto[gx0,gy0]=cell(last);
            int best=-1;double bestD=1e30;
            for(int rad=0;rad<=2*gs;rad++){
                if(best!=-1){
                    double mp=max(0.0,(double)(rad-1))*min(cW,cH);
                    if(mp>bestD*1.5)break;
                }
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad&&abs(dy)!=rad)continue;
                        int gx=gx0+dx,gy=gy0+dy;
                        if(gx<0||gx>=gs||gy<0||gy>=gs)continue;
                        for(int id:gr[idx(gx,gy)]){
                            if(!vis[id]){double d=ddist(last,id);if(d<bestD){bestD=d;best=id;}}
                        }
                    }
                }
                if(best!=-1&&rad>0)break;
            }
            t[step]=best;vis[best]=true;
            auto[gxb,gyb]=cell(best);auto&v=gr[idx(gxb,gyb)];v.erase(find(v.begin(),v.end(),best));
        }
        t[N]=startCity;
        return t;
    };

    vector<int> bestTour = buildNN(0);
    double bestCost = tourCost(bestTour);

    // Try a few random starts
    {
        mt19937 rng(42);
        int tries = min(10, max(1, (int)(0.3/max(0.001, elapsed()/(1+0)))));
        for(int tr=0; tr<tries && elapsed()<0.5; tr++){
            int sc = rng()%N;
            auto t = buildNN(sc);
            // Rotate so 0 is first
            int zp=-1;
            for(int i=0;i<N;i++) if(t[i]==0){zp=i;break;}
            if(zp!=0){
                vector<int> rt(N+1);
                for(int i=0;i<N;i++) rt[i]=t[(zp+i)%N];
                rt[N]=0; t=rt;
            }
            double c=tourCost(t);
            if(c<bestCost){bestCost=c;bestTour=t;}
        }
    }

    vector<int>& tour = bestTour;
    double curCost = bestCost;

    // 2-opt local search
    auto do2opt = [&](){
        bool improved=true;
        int window=min(N-1, max(100, N/5));
        if(N>50000) window=50;
        if(N>100000) window=30;
        while(improved && elapsed()<1.5){
            improved=false;
            for(int i=1;i<N-1&&elapsed()<1.45;i++){
                for(int j=i+1;j<min(i+window,N);j++){
                    int lo=i, hi=min(j+1,N);
                    double oldC=0;
                    for(int s=lo;s<=hi;s++) oldC+=edgeCost(s,tour[s-1],tour[s]);
                    reverse(tour.begin()+i, tour.begin()+j+1);
                    double newC=0;
                    for(int s=lo;s<=hi;s++) newC+=edgeCost(s,tour[s-1],tour[s]);
                    if(newC<oldC-1e-10){curCost+=newC-oldC;improved=true;}
                    else reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }
    };
    do2opt();

    // Prime-aware swaps
    for(int iter=0;iter<5&&elapsed()<1.85;iter++){
        bool imp=false;
        for(int t2=10;t2<=N;t2+=10){
            int pos=t2-1;
            if(is_prime[tour[pos]])continue;
            double bestDelta=0;int bestK=-1;
            int range=min(N-1,500);
            for(int k=max(1,pos-range);k<=min(N-1,pos+range);k++){
                if(k==pos||!is_prime[tour[k]])continue;
                set<int> aff={pos,pos+1,k,k+1};
                double oC=0;
                for(int s:aff)if(s>=1&&s<=N)oC+=edgeCost(s,tour[s-1],tour[s]);
                swap(tour[pos],tour[k]);
                double nC=0;
                for(int s:aff)if(s>=1&&s<=N)nC+=edgeCost(s,tour[s-1],tour[s]);
                double d=nC-oC;
                if(d<bestDelta){bestDelta=d;bestK=k;}
                swap(tour[pos],tour[k]);
            }
            if(bestK>=0){swap(tour[pos],tour[bestK]);curCost+=bestDelta;imp=true;}
        }
        if(!imp)break;
    }

    // Final 2-opt pass
    {
        int window=min(N-1,30);
        bool improved=true;
        while(improved&&elapsed()<1.95){
            improved=false;
            for(int i=1;i<N-1&&elapsed()<1.93;i++){
                for(int j=i+1;j<min(i+window,N);j++){
                    int lo=i,hi=min(j+1,N);
                    double oldC=0;for(int s=lo;s<=hi;s++)oldC+=edgeCost(s,tour[s-1],tour[s]);
                    reverse(tour.begin()+i,tour.begin()+j+1);
                    double newC=0;for(int s=lo;s<=hi;s++)newC+=edgeCost(s,tour[s-1],tour[s]);
                    if(newC<oldC-1e-10){curCost+=newC-oldC;improved=true;}
                    else reverse(tour.begin()+i,tour.begin()+j+1);
                }
            }
        }
    }

    cout<<N+1<<"\n";
    for(int i=0;i<=N;i++) cout<<tour[i]<<"\n";
}
